#!/usr/bin/env bash
# Fails if any tracked or staged file is game content (see CLAUDE.md "Never commit game content").
# Run it before committing: bash .github/scripts/no-game-content.sh
set -euo pipefail
cd "$(git rev-parse --show-toplevel)"
fail=0

# game files, generated code, save states, frame dumps, captures, logs, user data, mod spaces
bad=$(git ls-files --cached | grep -iE \
  '\.(xex|iso|mng|pe|dmp|state)$|(^|/)(LMA_full|lab|extracted|dumps|states|refs|frames|capture|userdata|mods)/|crates/game-blocks/parts/|(^|/)(last_run\.log|misses\.txt)$' || true)
if [ -n "$bad" ]; then
  echo "::error::game content is tracked; remove it (git rm --cached) and check .gitignore:"
  echo "$bad"
  fail=1
fi

# the committed game-blocks crate must stay the placeholder over stubs/, not lma-recomp's output
gb=lma-rs/crates/game-blocks
if git cat-file -p ":$gb/Cargo.toml" | grep -qE 'path = "parts/'; then
  echo "::error::$gb/Cargo.toml points at generated parts/; restore the placeholder and run: git update-index --skip-worktree $gb/Cargo.toml $gb/src/lib.rs"
  fail=1
fi
if git cat-file -p ":$gb/src/lib.rs" | grep -q 'GENERATED by lma-recomp'; then
  echo "::error::$gb/src/lib.rs is generated code; restore the placeholder (see above)"
  fail=1
fi

[ "$fail" = 0 ] && echo "no game content tracked"
exit "$fail"
